import { readFileSync } from 'node:fs';
import { loadVendorFile } from '../../../../../tools/node-vendor.mjs';
const root = './dist/typed/';
for (const f of ['tape','typed-wasm','typed-rv32','typed-rv32-inline','typed-rv32-loops','typed-rv32-kernel']) loadVendorFile('compiler/typed/' + f + '.js');
loadVendorFile('bench/host/rv32-interp.js');
const {setVendor} = await import(root+'vendor.js');
setVendor(globalThis);
const {Program} = await import(root+'program.js');
const {projectSource} = await import(root+'project.js');
const {benchCase,evaluate,casesFrom,agrees}=await import(root+'evaluate.js');
const {storeOf}=await import(root+'ir.js');
const {imageFromCode,lowerToImage,runImage}=await import(root+'backend/index.js');
const repo='/home/manuel/code/wesen/2026-10-20--ds-js-os/';
const parts=['state','position','moves','search'];
const files=Object.fromEntries(parts.map(n=>[n+'.typed',readFileSync(repo+'apps/typed/chess/'+n+'.typed','utf8')]));
const smokeFiles={'helpers.typed':'record TestState { score: i32; running: bool; }\nfunction getCell(b: buffer, i: i32): i32 { return b.charCodeAt(i); }',
'main.typed':'function smoke(b: buffer, state: TestState, n: i32, advanced: bool): i32 { let i = 0; while (i < n && i < b.length) { i = i + 1; if (i === 1) { continue; } if (advanced) { break; } } state.running = advanced; state.score = getCell(b, i - 1) - 65536; b.setCharCodeAt(0, state.score); return state.score; }',
'project.json':JSON.stringify({sources:['helpers.typed','main.typed'],entries:['smoke'],inputs:{smoke:{b:{cells:[0,65535,7]},state:{record:{score:0,running:0}},n:{oneOf:[2]},advanced:1}}})};
const ps=projectSource('probe',smokeFiles);
const smoke=Program.fromProject(ps);
console.log('smoke', smoke.status, smoke.error, smoke.options.entries, smoke.fns());
if(smoke.status==='ok') console.log('smoke result',smoke.check({count:1}).fns.map(f=>[f.fn,f.agree,f.bothTrap]), smoke.exec('smoke',[[0,65535,7],{score:0,running:0},2,true]),new Program(ps.name,ps.source,{inputs:ps.meta.inputs,entries:['smoke']}).check({count:1}).fns.map(f=>f.fn));
const eng=projectSource('chess-probe',{...files,'project.json':JSON.stringify({sources:parts.map(n=>n+'.typed')})});
const p=Program.fromProject(eng);
console.log('original engine',p.status,p.error,eng.source.length,p.fns().length);
if(p.status!=='ok') process.exit(1);
const st=storeOf(p.head.value);
const fixtures=JSON.parse(readFileSync(repo+'bench/reference/chess/reference-positions.json','utf8')).positions;
function board(fen,len=9216) {
 const [ranks,side,castle,ep,half,full]=fen.split(' ');
 const cells=Array(len).fill(0);
 for (const [rank,row] of ranks.split('/').entries()) {
  let file=0;
  for(const ch of row) {
   if(Number(ch)){file+=Number(ch);continue;}
   const sq=rank*16+file++;
   cells[sq]=' PNBRQK  pnbrqk'.indexOf(ch);
   if(ch==='K') cells[131]=sq;
   if(ch==='k') cells[132]=sq;
  }
 }
 cells[128]=Number(side==='b');
 for(const [i,ch] of [...'KQkq'].entries()) if(castle.includes(ch)) cells[129]+=2**i;
 cells[130]=ep==='-'?128:(8-Number(ep[1]))*16+ep.charCodeAt(0)-97;
 cells[133]=Number(half);cells[134]=Number(full);return cells;
}
const ref=globalThis.typedRv32.compile(eng.source,[],undefined);
const image=imageFromCode('chess_ref',ref.image,ref.entries);
const our=lowerToImage(p.head).image;
console.log('RV32 lowered', ref.image.length,our.value.byteLength);
const lookup=Object.fromEntries(Object.keys(st.frontEnd.records.WorldState).map((k,i)=>[k,i*4]));
const zero={record:Object.fromEntries(Object.keys(lookup).map(k=>[k,0]))};
for(const f of fixtures) {
 const k=benchCase(st,'chessPerft',{board:{cells:board(f.fen,2048)},depth:1});
 const r=evaluate(st,k.fn,k.args,k.memory,{limit:20000});
 const g=runImage(image,k.fn,k.args,k.memory,{limit:200000});
 const h=runImage(our,k.fn,k.args,k.memory,{limit:200000});
 console.log('perft1',f.name,r.result,r.steps,r.limit,g.result,g.steps,h.result,h.steps,agrees(r,g),agrees(r,h));
}
for(const name of ['en-passant-legal','promotion-and-underpromotion','quiet-mate-in-two','stalemate','mate-in-one','opening','defended-rook','castling-both-sides']) {
 const f=fixtures.find(x=>x.name===name);
 for(const [depth,budget,advanced] of [[2,2,0],[2,2,1],[2,4,1],[1,1800,1],[3,1600,1]]) {
 const start=benchCase(st,'chessStartSearch',{board:{cells:board(f.fen)},state:zero,depth,budget,advanced});
 const [b,s]=start.args;
 const r=evaluate(st,start.fn,start.args,start.memory,{limit:20000});
 const w=evaluate(st,'chessSearchSlice',[b,s,2048],r.bytes,{limit:5e6});
 const v=new DataView(w.bytes.buffer);
 console.log('start+slice',name,depth,budget,advanced,r.steps+w.steps,w.limit,...['running','nodes','score','completed','bestMove'].map(k=>v.getInt32(s+lookup[k],true)));
 }
}
