ticket=ttmp/2026/11/26/IRWB-017--chess-search-corpus-project
python3 - "$ticket/.probe/run.mjs" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1])
s=p.read_text()
p.write_text(s[:s.index('for(const name of')]+'''
console.log('WorldState', st.frontEnd.records.WorldState);
const shim=\\`function chessSearch(board: buffer, state: WorldState, depth: i32, budget: i32, advanced: bool): i32 {
 chessStartSearch(board, state, depth, budget, advanced);
 while (state.running) { chessSearchStep(board, state); }
 return state.bestMove;
}\\`;
const searchInputs=(fen,budget,advanced)=>({board:{cells:board(fen)},state:zero,depth:{oneOf:[1,2,3]},budget,advanced});
const test=fixtures.find(f=>f.name==='promotion-and-underpromotion');
const pin=fixtures.find(f=>f.name==='en-passant-pinned');
const inputs={chessSearch:searchInputs(test.fen,[2,3],{bool:true}),chessPerft:{board:{cells:board(pin.fen,2048)},depth:1}};
const q=new Program('chess_check_probe',eng.source+shim,{entries:['chessSearch','chessPerft'],inputs});
console.log('shim ingest',q.status,q.error);
const ss=storeOf(q.head.value);
const offsets=Object.fromEntries(Object.entries(ss.frontEnd.records.WorldState).map(([k,v])=>[k,v.offset]));
function outcome(res,k) {
 const v=new DataView(res.bytes.buffer,res.bytes.byteOffset,res.bytes.byteLength), s=k.args[1];
 return [res.result,res.steps,res.trap,res.limit,...['running','nodes','score','completed','bestMove'].map(k=>v.getInt32(s+offsets[k],true))];
}
for(const d of [1,2,3]) for(const b of [2,3]) for(const a of [0,1]) {
 const k=benchCase(ss,'chessSearch',{...searchInputs(test.fen,b,a),depth:d});
 console.log('bounded',d,b,a,outcome(evaluate(ss,k.fn,k.args,k.memory,{limit:20000}),k));
}
const probeRef=globalThis.typedRv32.compile(q.source,[],undefined);
const ri=imageFromCode('chess_check_ref',probeRef.image,probeRef.entries);
console.log('reference differential',q.check({count:8,against:(fn,k)=>runImage(ri,fn,k.args,k.memory,{limit:2e5,counts:false})}).fns);
const speed=await q.pipeline('speed',{count:4});
console.log('speed',speed.steps.map(s=>[s.pass,s.edits,s.rejected]));
console.log('checked',q.check({count:20}).fns);
const opt=lowerToImage(q.head).image;
for(const name of ['mate-in-one','mate-in-one-black','stalemate','checkmate','quiet-mate-in-two','defended-rook']) {
 const f=fixtures.find(x=>x.name===name);
 const d=name==='quiet-mate-in-two'?3:1;
 const k=benchCase(ss,'chessSearch',{...searchInputs(f.fen,1600,1),depth:d});
 const res=evaluate(ss,k.fn,k.args,k.memory,{limit:2e7});
 const r=runImage(ri,k.fn,k.args,k.memory,{limit:3e7,counts:false});
 const h=runImage(opt,k.fn,k.args,k.memory,{limit:3e7,counts:false});
 console.log('completed',name,outcome(res,k),outcome(r,k),outcome(h,k),agrees(res,r),agrees(res,h));
}
'''.replace('\\\`','\`'))
